router.get('/dashboard', wrap(async (_req, res) => {
  const [byStatus, totals, recentProjects, activity, upcomingMilestones, overdueTasks, archived, criticalRisk] = await Promise.all([
    Project.aggregate([{ $match: { status: { $ne: 'Archived' } } }, { $group: { _id: '$status', value: { $sum: 1 } } }]),
    Project.aggregate([{ $match: { status: { $ne: 'Archived' } } }, { $group: { _id: null, healthScore: { $avg: '$healthScore' }, estimatedBudget: { $sum: { $ifNull: ['$estimatedBudget', 0] } }, actualExpenses: { $sum: { $ifNull: ['$actualExpenses', 0] } }, recordedRevenue: { $sum: { $ifNull: ['$recordedRevenue', 0] } } } }]),
    Project.find({ status: { $ne: 'Archived' } }).sort({ updatedAt: -1 }).limit(5).select('name status healthScore estimatedBudget actualExpenses recordedRevenue updatedAt progress').lean(),
    ActivityLog.find().sort({ createdAt: -1 }).limit(8).lean(),
    Milestone.countDocuments({ status: { $in: ['Not Started', 'In Progress'] }, dueDate: { $gte: new Date() } }),
    Task.countDocuments({ status: { $ne: 'Done' }, dueDate: { $lt: new Date() } }),
    Project.countDocuments({ status: 'Archived' }),
    Project.countDocuments({ riskLevel: 'Critical', status: { $ne: 'Archived' } })
  ]);
  const [aggregateFinance, aggregateReceipts] = await Promise.all([
    BusinessTransaction.aggregate([{ $match: { kind: { $in: ['expense','reversal'] }, status: 'recorded', currency: 'INR' } }, { $group: { _id: null, total: { $sum: { $cond: [{ $eq: ['$kind','reversal'] }, { $multiply: ['$amountMinor',-1] }, '$amountMinor'] } } } }]),
    BusinessPayment.aggregate([{ $match: { status: 'completed', currency: 'INR' } }, { $group: { _id: null, total: { $sum: '$amountMinor' } } }])
  ]);
  const alertsSince=new Date(Date.now()-7*86400000),failuresSince=new Date(Date.now()-30*86400000);
  const [enabledAutomations,failedAutomations,securityAlerts,worker]=await Promise.all([
    AutomationWorkflow.countDocuments({enabled:true}),
    AutomationExecution.countDocuments({status:'failed',createdAt:{$gte:failuresSince}}),
    SecurityEvent.countDocuments({result:{$in:['failure','denied']},createdAt:{$gte:alertsSince}}),
    AutomationWorkerStatus.findById('scheduler').select('status lastHeartbeat').lean()
  ]);
  const workerStatus=worker&&Date.now()-new Date(worker.lastHeartbeat).getTime()<90000?worker.status:'not-running';
  const aggregate = totals[0];
  const count = (status: string) => byStatus.find(row => row._id === status)?.value || 0;
  res.json({ data: { metrics: { total: byStatus.reduce((sum, row) => sum + row.value, 0), active: count('Active'), development: count('In Development'), completed: count('Completed'), paused: count('Paused'), archived, criticalRisk, upcomingMilestones, overdueTasks, healthScore: aggregate?.healthScore == null ? null : Math.round(aggregate.healthScore), estimatedBudget: aggregate?.estimatedBudget || 0, actualExpenses: (aggregateFinance[0]?.total || 0) / 100, recordedRevenue: (aggregateReceipts[0]?.total || 0) / 100 }, status: byStatus.map(row => ({ name: row._id, value: row.value })), recentProjects, activity, integrations: { github: Boolean(process.env.GITHUB_TOKEN), deploymentProviders: Boolean(process.env.VERCEL_ACCESS_TOKEN || process.env.RENDER_API_KEY), cloudflare: Boolean(process.env.CLOUDFLARE_API_TOKEN), aiHub: Boolean(process.env.KENORA_AI_HUB_URL&&process.env.KENORA_AI_HUB_TOKEN) }, operations:{enabledAutomations,failedAutomations,securityAlerts,automationWorker:workerStatus} } });
}));
