router.post('/documents/upload',acceptDocument,wrap(async(req,res)=>{if(!req.file)return res.status(400).json({error:{message:'Choose a document to upload.'}});let key:string|undefined,persisted=false;try{const input=z.object({project:z.string().optional(),documentType:z.string().max(80).optional()}).parse(req.body);if(input.project&&!await Project.exists({_id:input.project}))return res.status(400).json({error:{message:'Selected project does not exist.'}});const checked=await validateDocumentFile(req.file);const scan=await scanDocument({...req.file,originalname:checked.name});key=await documentStorage.put(req.file.path);const ext=path.extname(checked.name).toLowerCase(),doc=await StoredDocument.create({name:checked.name,project:input.project,documentType:input.documentType||ext.slice(1).toUpperCase(),storageName:key,mimeType:req.file.mimetype,size:checked.size});persisted=true;await ActivityLog.create({action:'Document uploaded',description:`Uploaded ${doc.name}`,entityType:'Document',entityId:doc._id});await recordSecurityEvent(req,'document.upload','success',{actorId:res.locals.user._id,targetType:'Document',targetId:doc._id,metadata:{scan:scan.verdict}});res.status(201).json({data:doc})}catch(error){if(key&&!persisted)await documentStorage.delete(key).catch(()=>{});await recordSecurityEvent(req,'document.upload','failure',{actorId:res.locals.user._id}).catch(()=>{});throw error}finally{await fs.promises.rm(req.file.path,{force:true})}}));
