const recordModules=['clients','leads','services','proposals','invoices','finance','security','technical-debt','testing','deployments','infrastructure','documents','notifications','backups'] as const;
const recordFields:Record<string,string[]>={clients:['email','phone','company','status','notes'],leads:['email','phone','source','status','estimatedValue','notes'],services:['description','price','currency','billingPeriod','status'],proposals:['client','amount','currency','status','validUntil','notes'],invoices:['client','amount','currency','status','dueDate','paidAt','notes'],finance:['kind','amount','currency','date','category','project','paymentStatus','notes'],security:['project','severity','category','status','affectedComponent','remediation','discoveredAt','resolvedAt'], 'technical-debt':['project','priority','estimatedHours','status','resolutionPlan'],testing:['project','testType','result','source','verifiedAt','notes'],deployments:['project','provider','environment','url','status','deployedAt'],infrastructure:['project','provider','resourceType','region','monthlyCost','status'],documents:['project','documentType','url','version','notes'],notifications:['message','status','readAt'],backups:['backupType','status','createdAt','notes']};
const fieldsSchema=z.record(z.string().max(60).regex(/^[a-zA-Z][a-zA-Z0-9]*$/),z.union([z.string().max(4000),z.number().finite(),z.boolean(),z.null()]));
router.get('/records/:module',wrap(async(req,res)=>{const moduleName=req.params.module;if(!recordModules.includes(moduleName as any))return res.status(404).json({error:{message:'Unknown record type'}});const {page,limit,skip}=paging(req,50),filter:any={module:moduleName};if(req.query.project)filter['fields.project']=String(req.query.project);if(req.query.q)filter.title={$regex:String(req.query.q).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),$options:'i'};const [rows,total]=await Promise.all([WorkspaceRecord.find(filter).sort(sorting(req,['updatedAt','title','createdAt'],{updatedAt:-1})).skip(skip).limit(limit).lean(),WorkspaceRecord.countDocuments(filter)]);res.json({data:rows,meta:{page,limit,total,pages:Math.ceil(total/limit)}})}));
router.post('/records/:module',wrap(async(req,res)=>{const moduleName=req.params.module;if(!recordModules.includes(moduleName as any))return res.status(404).json({error:{message:'Unknown record type'}});const input=z.object({title:z.string().trim().min(1).max(200),fields:fieldsSchema.default({})}).parse(req.body);const allowed=recordFields[moduleName];const invalid=Object.keys(input.fields).find(k=>!allowed.includes(k));if(invalid)return res.status(400).json({error:{message:`Field ${invalid} is not supported for ${moduleName}`}});if(typeof input.fields.project==='string'&&!await Project.exists({_id:input.fields.project}))return res.status(400).json({error:{message:'Selected project does not exist.'}});const row=await WorkspaceRecord.create({module:moduleName,...input});await ActivityLog.create({action:`${moduleName} record created`,description:`Created ${moduleName} record ${row.title}`,entityType:moduleName,entityId:row._id});res.status(201).json({data:row})}));
router.patch('/records/:module/:id',wrap(async(req,res)=>{const moduleName=req.params.module;if(!recordModules.includes(moduleName as any))return res.status(404).json({error:{message:'Unknown record type'}});const input=z.object({title:z.string().trim().min(1).max(200).optional(),fields:fieldsSchema.optional()}).parse(req.body);if(input.fields){const invalid=Object.keys(input.fields).find(k=>!recordFields[moduleName].includes(k));if(invalid)return res.status(400).json({error:{message:`Field ${invalid} is not supported for ${moduleName}`}});if(typeof input.fields.project==='string'&&!await Project.exists({_id:input.fields.project}))return res.status(400).json({error:{message:'Selected project does not exist.'}})}const row=await WorkspaceRecord.findOneAndUpdate({_id:req.params.id,module:moduleName},{$set:input},{new:true,runValidators:true});if(!row)return res.status(404).json({error:{message:'Record not found'}});res.json({data:row})}));
