router.get('/export',wrap(async(_req,res)=>{const [projects,folders,tasks,milestones,records,categories,technologies]=await Promise.all([Project.find().lean(),Folder.find().lean(),Task.find().lean(),Milestone.find().lean(),WorkspaceRecord.find().lean(),Category.find().lean(),Technology.find().lean()]);res.json({data:{format:'kenoratech-metadata-v1',exportedAt:new Date().toISOString(),projects,folders,tasks,milestones,records,categories,technologies}})}));
const importRow = async (model: any, raw: Record<string, unknown>) => {
  const allowed = new Set(Object.keys(model.schema.paths).filter((key: string) => key !== '__v'));
  const clean = Object.fromEntries(Object.entries(raw).filter(([key]) => allowed.has(key)));
  if (!clean._id || !(await model.exists({ _id: clean._id }))) {
    await model.create(clean);
    return true;
  }
  return false;
};
const importCollections = async (input: Record<string, any>) => {
  const counts: Record<string, { created: number; skipped: number; failed: number }> = {};
  const failures: Array<{collection:string;id?:string;message:string}> = [];
  const collections: Array<[string, any]> = [['projects',Project],['folders',Folder],['categories',Category],['technologies',Technology],['tasks',Task],['milestones',Milestone],['records',WorkspaceRecord]];
  for (const [name, model] of collections) {
    counts[name] = { created: 0, skipped: 0, failed: 0 };
    for (const raw of input[name] || []) {
      try { if (await importRow(model, raw)) counts[name].created++; else counts[name].skipped++; }
      catch { counts[name].failed++; failures.push({collection:name,id:raw?._id?String(raw._id):undefined,message:'Invalid row or conflicting unique value.'}); }
    }
  }
  return {counts,failures};
};
const validateMetadataReferences = async (input:Record<string,any>) => {
  const collections:Record<string,any[]>={projects:input.projects||[],folders:input.folders||[],categories:input.categories||[],technologies:input.technologies||[],tasks:input.tasks||[],milestones:input.milestones||[],records:input.records||[]};
  const models:Record<string,any>={projects:Project,folders:Folder,categories:Category,milestones:Milestone};
  const ids=new Map<string,Set<string>>();const issues:string[]=[];
  for(const [name,rows] of Object.entries(collections)){const seen=new Set<string>();for(const row of rows){if(row._id){const id=String(row._id);if(seen.has(id))issues.push(`Duplicate ${name} ID ${id}.`);seen.add(id)}}ids.set(name,seen)}
  const exists=async(name:string,value:any)=>{if(!value)return true;if(typeof value==='string'&&!/^[a-f\d]{24}$/i.test(value))return false;if(ids.get(name)?.has(String(value)))return true;const model=models[name];return model?Boolean(await model.exists({_id:value})):false};
  for(const row of collections.projects){if(!(await exists('categories',row.category)))issues.push(`Project ${row.name||row._id} references a missing category.`);if(!(await exists('folders',row.folder)))issues.push(`Project ${row.name||row._id} references a missing folder.`)}
  for(const row of collections.folders){if(!(await exists('folders',row.parent)))issues.push(`Folder ${row.name||row._id} references a missing parent.`);if(!(await exists('projects',row.project)))issues.push(`Folder ${row.name||row._id} references a missing project.`)}
  for(const row of collections.tasks){if(!(await exists('projects',row.project)))issues.push(`Task ${row.title||row._id} references a missing project.`);if(!(await exists('milestones',row.milestone)))issues.push(`Task ${row.title||row._id} references a missing milestone.`)}
  for(const row of collections.milestones){if(!(await exists('projects',row.project)))issues.push(`Milestone ${row.name||row._id} references a missing project.`);for(const id of row.dependencies||[])if(!(await exists('milestones',id)))issues.push(`Milestone ${row.name||row._id} references a missing dependency.`)}
  for(const row of collections.records)if(!(await exists('projects',row.fields?.project)))issues.push(`Workspace record ${row.title||row._id} references a missing project.`);
  return issues;
};
router.post('/import',wrap(async(req,res)=>{
  const input=z.object({format:z.string(),projects:z.array(z.record(z.string(),z.any())).max(5000).optional(),folders:z.array(z.record(z.string(),z.any())).max(5000).optional(),categories:z.array(z.record(z.string(),z.any())).max(5000).optional(),technologies:z.array(z.record(z.string(),z.any())).max(5000).optional(),tasks:z.array(z.record(z.string(),z.any())).max(10000).optional(),milestones:z.array(z.record(z.string(),z.any())).max(10000).optional(),records:z.array(z.record(z.string(),z.any())).max(20000).optional()}).parse(req.body);
  if(input.format!=='kenoratech-metadata-v1')return res.status(400).json({error:{message:'Unsupported metadata export format'}});
  const issues=await validateMetadataReferences(input);if(issues.length)return res.status(400).json({error:{message:`Import validation failed: ${issues.slice(0,5).join(' ')}`}});
  const result=await importCollections(input),counts=result.counts;
  res.json({data:{...result,status:result.failures.length?'partial':'complete',createdProjects:counts.projects.created,duplicateProjects:counts.projects.skipped,createdFolders:counts.folders.created,duplicateFolders:counts.folders.skipped}});
}));
