  const folderKeys=new Set<string>();for(const row of backup.records.folders||[]){if(await Folder.exists({_id:row._id}))continue;const key=`${String(row.parent??'root')}/${row.name}`;if(folderKeys.has(key)||await Folder.exists({parent:row.parent??null,name:row.name,_id:{$ne:row._id}}))conflicts.push(`folders.parent/name=${key}`);folderKeys.add(key)}
